class Canvas:
    """Plain RGB bytearray canvas with tiny drawing primitives."""

    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.px = bytearray(bytes(bg) * (w * h))

    def set(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            o = (y * self.w + x) * 3
            self.px[o:o + 3] = bytes(c)

    def rect(self, x, y, w, h, c):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(c) * (x1 - x0)
        for yy in range(y0, y1):
            o = (yy * self.w + x0) * 3
            self.px[o:o + len(row)] = row

    def hline(self, x0, x1, y, c, thick=1):
        for t in range(thick):
            self.rect(x0, y + t, x1 - x0, 1, c)

    def vline(self, x, y0, y1, c, thick=1):
        for t in range(thick):
            self.rect(x + t, y0, 1, y1 - y0, c)

    def line(self, x0, y0, x1, y1, c):
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            self.set(x0, y0, c)
            if x0 == x1 and y0 == y1:
                return
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def circle(self, cx, cy, r, c):
        for dy in range(-r, r + 1):
            dx = int((r * r - dy * dy) ** 0.5)
            self.rect(cx - dx, cy + dy, 2 * dx + 1, 1, c)

    def ring(self, cx, cy, r, c):
        import math
        steps = max(24, 6 * r)
        for i in range(steps):
            a = 2 * math.pi * i / steps
            self.set(int(cx + r * math.cos(a)), int(cy + r * math.sin(a)), c)

    def poly(self, pts, c):
        """Scanline fill of a simple polygon (list of (x, y))."""
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        y0, y1 = max(0, int(min(ys))), min(self.h - 1, int(max(ys)))
        n = len(pts)
        for y in range(y0, y1 + 1):
            xs = []
            for i in range(n):
                x0, yy0 = pts[i]
                x1, yy1 = pts[(i + 1) % n]
                if (yy0 <= y < yy1) or (yy1 <= y < yy0):
                    t = (y - yy0) / (yy1 - yy0)
                    xs.append(x0 + t * (x1 - x0))
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                xa = max(0, int(xs[k]))
                xb = min(self.w - 1, int(xs[k + 1]))
                if xb >= xa:
                    self.rect(xa, y, xb - xa + 1, 1, c)


class Text:
    """Bitmap text using the loaded fonts."""

    def __init__(self, fonts):
        self.fonts = fonts

    def width(self, name, s):
        _, glyphs = self.fonts[name]
        space_w = glyphs[" "][0]
        total = 0
        for ch in s:
            g = glyphs.get(ch)
            total += g[0] if g else space_w
        return total

    def draw(self, cv, name, x, y, s, color):
        height, glyphs = self.fonts[name]
        space_w = glyphs[" "][0]
        cx = x
        for ch in s:
            g = glyphs.get(ch)
            if g is None:
                cx += space_w
                continue
            w, bits = g
            rb = (w + 7) // 8
            for yy in range(height):
                row = bits[yy * rb:(yy + 1) * rb]
                for xx in range(w):
                    if row[xx // 8] & (0x80 >> (xx % 8)):
                        cv.set(cx + xx, y + yy, color)
            cx += w
        return cx

    def wrap(self, name, s, maxw):
        """Greedy word wrap; returns a list of lines (never empty)."""
        words = s.split(" ")
        lines = []
        cur = ""
        for word in words:
            trial = word if not cur else cur + " " + word
            if self.width(name, trial) <= maxw:
                cur = trial
            else:
                if cur:
                    lines.append(cur)
                while self.width(name, word) > maxw and len(word) > 1:
                    # hard-split an over-long word
                    cut = len(word)
                    while cut > 1 and self.width(name, word[:cut]) > maxw:
                        cut -= 1
                    lines.append(word[:cut])
                    word = word[cut:]
                cur = word
        if cur or not lines:
            lines.append(cur)
        return lines

# ---------------------------------------------------------------- PNG out
def _paeth(a, b, c):
    p = a + b - c
    pa = abs(p - a)
    pb = abs(p - b)
    pc = abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c


def _filter_row(kind, row, prev):
    n = len(row)
    out = bytearray(n)
    if kind == 0:
        out[:] = row
    elif kind == 1:
        out[:3] = row[:3]
        for i in range(3, n):
            out[i] = (row[i] - row[i - 3]) & 0xFF
    elif kind == 2:
        if prev is None:
            out[:] = row
        else:
            for i in range(n):
                out[i] = (row[i] - prev[i]) & 0xFF
    elif kind == 3:
        for i in range(n):
            left = row[i - 3] if i >= 3 else 0
            up = prev[i] if prev is not None else 0
            out[i] = (row[i] - ((left + up) // 2)) & 0xFF
    else:
        for i in range(n):
            a = row[i - 3] if i >= 3 else 0
            b = prev[i] if prev is not None else 0
            c = prev[i - 3] if (prev is not None and i >= 3) else 0
            out[i] = (row[i] - _paeth(a, b, c)) & 0xFF
    return bytes(out)


def encode_png(cv):
    """Encode the canvas as PNG bytes; per-row greedy filter choice."""
    w, h = cv.w, cv.h
    raw = bytes(cv.px)
    stride = w * 3
    comp = zlib.compressobj(9)
    stream = bytearray()
    prev = None
    for y in range(h):
        row = raw[y * stride:(y + 1) * stride]
        best = None
        best_len = None
        for kind in range(5):
            trial = _filter_row(kind, row, prev)
            size = len(zlib.compress(trial, 6))
            if best_len is None or size < best_len:
                best = trial
                best_len = size
                best_kind = kind
        stream.append(best_kind)
        stream += best
        prev = row
    body = comp.compress(bytes(stream)) + comp.flush()

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", bytes(body)) + chunk(b"IEND", b""))


